```python
class MyClass:
    def __init__(self, arg):
        self.arg = arg
def func():
    arg = MyClass(42)
    if isinstance(arg, dict[str, int]):
        print("arg is a dict[str, int]")
    else:
        print("arg is not a dict[str, int]")
func()
```
